namespace Fanex.Razorbill.Module.Report.Controllers
{
    using System;
    using System.Collections.Generic;
    using System.Diagnostics.CodeAnalysis;
    using System.Web.Mvc;
    using Fanex.Razorbill.Module.Core.Exceptions;
    using Fanex.Razorbill.Module.Core.Security;
    using Fanex.Razorbill.Module.Core.Services.Impl;
    using Fanex.Razorbill.Module.Core.Utils;
    using Fanex.Razorbill.Module.Core.Web.Controllers;
    using Fanex.Razorbill.Module.Report.Criteria.Consolidation;
    using Fanex.Razorbill.Module.Report.ViewModels.Consolidation;
    using Fanex.Razorbill.Report.Services.Consolidation.Impl;
    using Fanex.Razorbill.Report.Services.Consolidation.Interface;
    using Sunplus.Agent.Model.Entities;

    /// <summary>
    /// Consolidate Report Controller.
    /// </summary>
    public class ConsolidateController : BaseController
    {
        private readonly IConsolidationReportService _consolidationService;

        //private const string FunctionKeyName = "ReportRequestTicket";
        private const string MainAction = "Index";

        public ConsolidateController() :
            this(null)
        {
        }

        public ConsolidateController(IConsolidationReportService reportService)
        {
            _consolidationService = reportService ?? new ConsolidationReportService();
        }

        [HttpGet]
        [ConsolidateAuthentication(AuthenticateAction.AuthenticationType.Read, MainAction)]
        public ActionResult Index()
        {            
            ViewBag.ReportMinDate = ReportDateTimeRange[0];
            return View();
        }

        [HttpPost]
        [ConsolidateAuthentication(AuthenticateAction.AuthenticationType.Read, MainAction)]
        [HandleActionErrorAttribute]
        public JsonResult GetCurrency()
        {
            var criteria = new Age_Rpt_ConsolidatedGroupSelCurrency
                {
                CustID = Convert.ToInt32(UserSession.Current.CustId)
            };

            var lstCurrency = _consolidationService.GetCurrency(criteria);
            return Json(lstCurrency, JsonRequestBehavior.AllowGet);
        }

        [HttpPost]
        [ConsolidateAuthentication(AuthenticateAction.AuthenticationType.Read, MainAction)]
        [HandleActionErrorAttribute]
        public JsonResult GetData(Age_Rpt_ConsolidatedGroup criteria)
        {
            criteria.BalanceUpDate = ReportService.BalanceUp.BalanceUpDay;
            criteria.CustID = Convert.ToInt32(UserSession.Current.CustId);
            var data = _consolidationService.GetData(criteria);
            Session[CacheServiceKey.SessionKeyConsolidateReport] = data;
            return Json(data, JsonRequestBehavior.AllowGet);
        }

        [HttpGet]
        [ConsolidateAuthentication(AuthenticateAction.AuthenticationType.Read, MainAction)]
        public ActionResult ExportExcel(Age_Rpt_ConsolidatedGroup criteria)
        {
            return File(_consolidationService.ExportExcel(criteria, (List<ConsolidateReport>)Session[CacheServiceKey.SessionKeyConsolidateReport]).ToArray(), "application/vnd.ms-excel", "Consolidated.xls");
        }

        private sealed class ConsolidateAuthentication : AuthenticateAction
        {
            public ConsolidateAuthentication(AuthenticationType authenticationType, string mainAction) : base(authenticationType, mainAction)
            {
            }

            protected override bool GrantedRead()
            {
                //return false;
                return (UserSession.Current != null && UserSession.Current.IsShowConsolidatedReport);
            }
        }

    }
}
